import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1793828433000}`),a={name:`guide/faq.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h1><p>本页收集使用框架时最常遇到的问题与排查方法，按装配、操作与协议、数据与安全、版本与能力范围分组。</p><h2 id="装配" tabindex="-1">装配 <a class="header-anchor" href="#装配" aria-label="Permalink to “装配”">​</a></h2><h3 id="启动时报-kernel-capability-004-说某个能力有多个候选" tabindex="-1">启动时报 KERNEL_CAPABILITY_004，说某个能力有多个候选 <a class="header-anchor" href="#启动时报-kernel-capability-004-说某个能力有多个候选" aria-label="Permalink to “启动时报 KERNEL_CAPABILITY_004，说某个能力有多个候选”">​</a></h3><p>同一能力有两个以上显式 Provider，内核无法替应用选择。在配置里指定提供者，或在代码里调用 <code>UseProvider</code>：</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;XiHan&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Providers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;caching.distributed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xihan.caching.redis&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } } }</span></span></code></pre></div><p>清单 ID 写在各包页的信息表里；规则见<a href="./modularity#选择-provider">能力包与清单</a>。</p><h3 id="启动时报-kernel-capability-001-说依赖没有提供者" tabindex="-1">启动时报 KERNEL_CAPABILITY_001，说依赖没有提供者 <a class="header-anchor" href="#启动时报-kernel-capability-001-说依赖没有提供者" aria-label="Permalink to “启动时报 KERNEL_CAPABILITY_001，说依赖没有提供者”">​</a></h3><p>某个特性的 <code>Requires</code> 里有一个必需能力，但应用没有加入任何提供它的特性。错误信息给出需求方与能力 ID，加入对应的默认实现或 Provider（<code>UseFeature&lt;...&gt;()</code>）即可；不需要它时把依赖标为可选。</p><h3 id="引用了-provider-包-但运行时仍在用内存实现" tabindex="-1">引用了 Provider 包，但运行时仍在用内存实现 <a class="header-anchor" href="#引用了-provider-包-但运行时仍在用内存实现" aria-label="Permalink to “引用了 Provider 包，但运行时仍在用内存实现”">​</a></h3><p>只引用包不会生效，还要在 <code>AddXiHan</code> 里 <code>UseFeature&lt;...&gt;()</code> 加入它的特性。加入后看启动日志里的能力图谱：被顶替的默认实现不再出现在该能力下，完全没有被选中的节点不装配。</p><h3 id="中间件第一次调用时报「没有注册服务」" tabindex="-1">中间件第一次调用时报「没有注册服务」 <a class="header-anchor" href="#中间件第一次调用时报「没有注册服务」" aria-label="Permalink to “中间件第一次调用时报「没有注册服务」”">​</a></h3><p>用 <code>AppBuilder.ConfigurePipeline</code> 或 <code>Pipeline.UseAt&lt;T&gt;</code> 登记的中间件，内核不替应用注册类型，需要自己 <code>builder.Services.AddSingleton&lt;T&gt;()</code>。在特性里用 <code>context.AddMiddleware&lt;T&gt;()</code> 登记则由内核一并注册。</p><h3 id="中间件里取不到主体或租户" tabindex="-1">中间件里取不到主体或租户 <a class="header-anchor" href="#中间件里取不到主体或租户" aria-label="Permalink to “中间件里取不到主体或租户”">​</a></h3><p>主体在 Authenticate 阶段、租户在 Tenant 阶段之后才写入上下文。中间件要放在这些阶段之后；同一阶段内依赖另一个包中间件的产出时，必须用 <code>After&lt;TMiddleware, TOther&gt;()</code> 声明次序，不能依赖归属字典序。见<a href="./pipeline#排序规则">执行管道</a>。</p><h3 id="怎样查看最终的能力图谱与管道顺序" tabindex="-1">怎样查看最终的能力图谱与管道顺序 <a class="header-anchor" href="#怎样查看最终的能力图谱与管道顺序" aria-label="Permalink to “怎样查看最终的能力图谱与管道顺序”">​</a></h3><p>启动日志在 Information 级别打印两者。接了命令行宿主时运行 <code>graph</code> 与 <code>pipeline</code> 命令；代码里用 <code>App.DescribeGraph()</code> 与 <code>App.DescribePipeline()</code>。</p><h2 id="操作与协议" tabindex="-1">操作与协议 <a class="header-anchor" href="#操作与协议" aria-label="Permalink to “操作与协议”">​</a></h2><h3 id="编译报-xhg002" tabindex="-1">编译报 XHG002 <a class="header-anchor" href="#编译报-xhg002" aria-label="Permalink to “编译报 XHG002”">​</a></h3><p>操作的请求或响应类型没有登记到任何 <code>JsonSerializerContext</code>。在项目的序列化上下文上加 <code>[JsonSerializable(typeof(...))]</code>，见<a href="./operations#登记序列化类型与-schema">操作契约</a>。</p><h3 id="操作没有出现在-http-路由或-openapi-里" tabindex="-1">操作没有出现在 HTTP 路由或 OpenAPI 里 <a class="header-anchor" href="#操作没有出现在-http-路由或-openapi-里" aria-label="Permalink to “操作没有出现在 HTTP 路由或 OpenAPI 里”">​</a></h3><p>逐项检查：</p><ol><li>特性的 <code>Configure</code> 调用了 <code>context.AddGeneratedOperations()</code>，项目引用了 <code>Kernel.Generators</code>（以分析器方式）。</li><li>操作的 <code>Expose</code> 包含 <code>Expose.Http</code>；没写 <code>Expose</code> 时看程序集级 <code>OperationDefaults</code>。</li><li>操作的 <code>Stability</code> 不是 <code>Internal</code>。</li><li>应用加入了 <code>HttpProtocolFeature</code>，并在 <code>app.UseXiHan()</code> 之后调用了 <code>app.MapXiHanOperations()</code>。</li></ol><h3 id="两个操作启动时报-protocols-conflict-002" tabindex="-1">两个操作启动时报 PROTOCOLS_CONFLICT_002 <a class="header-anchor" href="#两个操作启动时报-protocols-conflict-002" aria-label="Permalink to “两个操作启动时报 PROTOCOLS_CONFLICT_002”">​</a></h3><p>两个操作推导出了同一条 HTTP 路由或同一个 gRPC 方法名，典型情况是请求都不含 <code>id</code> 的 <code>get</code> 与 <code>list</code>。按操作覆盖其中一条路由，见 <a href="./http">HTTP 与 OpenAPI</a>。</p><h3 id="调用返回-503-与-kernel-unavailable-001" tabindex="-1">调用返回 503 与 KERNEL_UNAVAILABLE_001 <a class="header-anchor" href="#调用返回-503-与-kernel-unavailable-001" aria-label="Permalink to “调用返回 503 与 KERNEL_UNAVAILABLE_001”">​</a></h3><p>应用还没有就绪或正在停止。看 <code>/health/startup</code> 与 <code>/health/ready</code> 的响应，找出状态不是 <code>Ready</code> 的特性；启动失败的原因记录在启动日志里。</p><h3 id="返回-503-与-kernel-unavailable-002、003-或-004" tabindex="-1">返回 503 与 KERNEL_UNAVAILABLE_002、003 或 004 <a class="header-anchor" href="#返回-503-与-kernel-unavailable-002、003-或-004" aria-label="Permalink to “返回 503 与 KERNEL_UNAVAILABLE_002、003 或 004”">​</a></h3><p>分别是限流、并发上限与熔断拒绝，来自 <code>XiHan:Kernel:Resilience</code> 的配置。响应的 <code>details.retryAfter</code> 给出建议的重试秒数，见<a href="./resilience">弹性与限流</a>。</p><h3 id="problem-details-的-detail-总是英文" tabindex="-1">Problem Details 的 detail 总是英文 <a class="header-anchor" href="#problem-details-的-detail-总是英文" aria-label="Permalink to “Problem Details 的 detail 总是英文”">​</a></h3><p>宿主按请求头 <code>Accept-Language</code> 选择区域，没有指定时用默认区域 <code>en-US</code>。应用自己的消息键要在对应语言的 <code>Localization/&lt;区域&gt;.json</code> 里有译文，并用 <code>AddMessageCatalog</code> 登记目录，见<a href="./localization">国际化</a>。</p><h3 id="什么时候是-401-什么时候是-403" tabindex="-1">什么时候是 401，什么时候是 403 <a class="header-anchor" href="#什么时候是-401-什么时候是-403" aria-label="Permalink to “什么时候是 401，什么时候是 403”">​</a></h3><p><code>SECURITY_DENIED_001</code>（未认证）与 <code>SECURITY_DENIED_003</code>（凭据无效、过期或签名不符）是 401，并带 <code>WWW-Authenticate</code> 质询；已认证但缺少权限（<code>SECURITY_DENIED_004</code>）或被策略拒绝（<code>SECURITY_DENIED_002</code>）是 403。</p><h2 id="数据与安全" tabindex="-1">数据与安全 <a class="header-anchor" href="#数据与安全" aria-label="Permalink to “数据与安全”">​</a></h2><h3 id="在后台任务里使用仓储报-persistence-unavailable-001" tabindex="-1">在后台任务里使用仓储报 PERSISTENCE_UNAVAILABLE_001 <a class="header-anchor" href="#在后台任务里使用仓储报-persistence-unavailable-001" aria-label="Permalink to “在后台任务里使用仓储报 PERSISTENCE_UNAVAILABLE_001”">​</a></h3><p>仓储只能在活动的工作单元内使用。操作调用由 Transaction 阶段自动开启工作单元；管道之外（后台循环、<code>IHostedFeature.StartAsync</code>、单例服务）要自己创建作用域并开启工作单元，写法见<a href="./uow">工作单元与事务</a>。</p><h3 id="重启后内存里的数据都没了" tabindex="-1">重启后内存里的数据都没了 <a class="header-anchor" href="#重启后内存里的数据都没了" aria-label="Permalink to “重启后内存里的数据都没了”">​</a></h3><p><code>Persistence.InMemory</code> 是开发与测试用的默认实现，数据只在进程内且容量有界。生产环境加入 <code>Persistence.EntityFrameworkCore</code> 或 <code>Persistence.SqlSugar</code>。</p><h3 id="新增多租户实体时报-persistence-validation-001" tabindex="-1">新增多租户实体时报 PERSISTENCE_VALIDATION_001 <a class="header-anchor" href="#新增多租户实体时报-persistence-validation-001" aria-label="Permalink to “新增多租户实体时报 PERSISTENCE_VALIDATION_001”">​</a></h3><p>实体实现了 <code>IMultiTenant</code>，但当前调用没有租户。检查认证主体是否带租户声明、调用方是否在 Baggage 里给出租户，或把配置 <code>XiHan:MultiTenancy:RequireTenant</code> 打开，让没有租户的调用在 Tenant 阶段就被拒绝，见<a href="./multi-tenancy">多租户</a>。</p><h2 id="版本与能力范围" tabindex="-1">版本与能力范围 <a class="header-anchor" href="#版本与能力范围" aria-label="Permalink to “版本与能力范围”">​</a></h2><h3 id="框架能用于生产吗" tabindex="-1">框架能用于生产吗 <a class="header-anchor" href="#框架能用于生产吗" aria-label="Permalink to “框架能用于生产吗”">​</a></h3><p>框架还在预览阶段，公开面多数标为 <code>Preview</code> 或 <code>Experimental</code>，正式版前仍可能调整。评估与新项目试点可以使用；需要稳定版本的生产系统等正式版。</p><h3 id="框架不提供哪些能力" tabindex="-1">框架不提供哪些能力 <a class="header-anchor" href="#框架不提供哪些能力" aria-label="Permalink to “框架不提供哪些能力”">​</a></h3><p>下列能力不由框架包装，原因是它们属于应用层需求，或 .NET 与成熟的专门组件已经覆盖。开发指南不为它们设章节。</p><table tabindex="0"><thead><tr><th>能力</th><th>做法</th></tr></thead><tbody><tr><td>机器人与消息通知渠道（邮件、短信、Telegram、钉钉、飞书、企业微信）</td><td>应用直接使用各渠道的 SDK 或 HTTP 接口，封装成应用自己的服务；需要异步发送时经消息子系统投递。<code>Messaging</code> 是队列、流与发布订阅子系统，不是通知渠道</td></tr><tr><td>实时通信（SignalR 封装）</td><td>直接使用 ASP.NET Core SignalR，Hub 的认证经 <code>XiHan</code> 认证方案交给内核，见<a href="./realtime">实时通信</a></td></tr><tr><td>网关与流量治理</td><td>反向代理与转发用 YARP 等专门组件；按操作的熔断、限流、并发上限由内核的 Resilience 阶段提供，见<a href="./resilience">弹性与限流</a></td></tr><tr><td>模板引擎</td><td>直接使用 Scriban、Fluid 等模板库</td></tr><tr><td>脚本引擎</td><td>不提供。需要隔离执行第三方逻辑时用插件，见<a href="./plugins">插件</a></td></tr><tr><td>搜索引擎</td><td>直接使用 Elasticsearch、OpenSearch 等的官方客户端</td></tr><tr><td>HTTP 客户端封装</td><td>使用 <code>IHttpClientFactory</code> 与 <code>Microsoft.Extensions.Http.Resilience</code></td></tr><tr><td>数据加解密</td><td>使用 <code>System.Security.Cryptography</code> 与 ASP.NET Core Data Protection。<code>Security</code> 是认证与授权子系统</td></tr><tr><td>对象映射</td><td>显式映射，或编译期生成代码的映射库，见<a href="./aot#对象映射">序列化与 Native AOT</a></td></tr><tr><td>序列化封装</td><td>直接使用 System.Text.Json 的源生成上下文</td></tr><tr><td>虚拟文件系统</td><td>使用 .NET 的 <code>IFileProvider</code> 与嵌入资源</td></tr><tr><td>设置</td><td>使用 .NET 配置与 <code>IOptionsMonitor</code>，远程配置见<a href="./configuration">配置与选项</a></td></tr><tr><td>声明式缓存特性</td><td>不提供，用 <code>ICacheStore</code>、<code>ICache</code>、<code>ISharedCache</code> 显式读写，见<a href="./caching">缓存与分布式锁</a></td></tr><tr><td>版本升级编排</td><td>由应用实现，需要单点执行时用调度子系统的领导选举</td></tr><tr><td>开发工具</td><td>命令行宿主的 <code>graph</code>、<code>pipeline</code>、<code>operations</code>、<code>invoke</code> 与 <code>xihan</code> 工具，见<a href="./command-line">命令行宿主</a></td></tr></tbody></table>`,46)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};